import{_ as t,o,c as a,a0 as i}from"./chunks/framework.DmGDJU50.js";const g=JSON.parse('{"title":"Command-Line Help for tardigrada","description":"","frontmatter":{},"headers":[],"relativePath":"reference/cli.md","filePath":"reference/cli.md"}'),d={name:"reference/cli.md"};function r(n,e,c,s,l,h){return o(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="command-line-help-for-tardigrada" tabindex="-1">Command-Line Help for <code>tardigrada</code> <a class="header-anchor" href="#command-line-help-for-tardigrada" aria-label="Permalink to &quot;Command-Line Help for `tardigrada`&quot;">​</a></h1><p>This document contains the help content for the <code>tardigrada</code> command-line program.</p><p>tardigrada — the per-machine, per-human age identity behind encrypted stores. <code>init</code> bootstraps the identity (generate + store, never clobbers); <code>show</code> prints the <code>age1…</code> recipient to share with tools that seal to it; <code>import</code>/<code>export</code> move key material between files and machines; <code>backend</code> inspects storage. <code>--json</code> is honored on every verb; the keyfile is the only secret tardigrade touches.</p><p><strong>Command Overview:</strong></p><ul><li><a href="#tardigrada"><code>tardigrada</code>↴</a></li><li><a href="#tardigrada-init"><code>tardigrada init</code>↴</a></li><li><a href="#tardigrada-show"><code>tardigrada show</code>↴</a></li><li><a href="#tardigrada-import"><code>tardigrada import</code>↴</a></li><li><a href="#tardigrada-export"><code>tardigrada export</code>↴</a></li><li><a href="#tardigrada-backend"><code>tardigrada backend</code>↴</a></li><li><a href="#tardigrada-manifest"><code>tardigrada manifest</code>↴</a></li></ul><h2 id="tardigrada" tabindex="-1"><code>tardigrada</code> <a class="header-anchor" href="#tardigrada" aria-label="Permalink to &quot;`tardigrada`&quot;">​</a></h2><p>tardigrada — the per-machine, per-human age identity behind encrypted stores. <code>init</code> bootstraps the identity (generate + store, never clobbers); <code>show</code> prints the <code>age1…</code> recipient to share with tools that seal to it; <code>import</code>/<code>export</code> move key material between files and machines; <code>backend</code> inspects storage. <code>--json</code> is honored on every verb; the keyfile is the only secret tardigrade touches.</p><p><strong>Usage:</strong> <code>tardigrada [OPTIONS] &lt;COMMAND&gt;</code></p><h6 id="commands" tabindex="-1"><strong>Commands:</strong> <a class="header-anchor" href="#commands" aria-label="Permalink to &quot;**Commands:**&quot;">​</a></h6><ul><li><code>init</code> — Bootstrap the age identity — generate + store it. Never clobbers an existing identity: a second <code>init</code> reports the current recipient and exits clean</li><li><code>show</code> — Print the <code>age1…</code> recipient of the stored identity — the value tools seal to (cuora vaults, tamias packs, rage recipients files). Goes to stdout bare (scriptable); backend/source context on stderr. Fails when no identity exists — run <code>tardigrada init</code> first</li><li><code>import</code> — Adopt an existing <code>identity.txt</code>-style keyfile as this machine&#39;s identity — parses the file, stores the identity at the configured path (overwrites whatever is there; the old key is gone for good)</li><li><code>export</code> — Write the identity keyfile out — mode <code>0600</code>, the same format <code>import</code> reads. <code>--out PATH</code> writes a file for moving between tools/machines; bare <code>export</code> prints the <code>AGE-SECRET-KEY-…</code> line to stdout (pipe it into another tool&#39;s keyfile, or <code>rage -e -i /dev/stdin</code>). This is the explicit escape hatch — the value is secret</li><li><code>backend</code> — Inspect the configured identity backend — always <code>file</code> in v1, plus the resolved keyfile path</li><li><code>manifest</code> — Capabilities, JSON shapes, env vars — agent self-discovery (always JSON)</li></ul><h6 id="options" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help (see a summary with &#39;-h&#39;)</li><li><code>-V, --version</code> — Print version</li></ul><h2 id="tardigrada-init" tabindex="-1"><code>tardigrada init</code> <a class="header-anchor" href="#tardigrada-init" aria-label="Permalink to &quot;`tardigrada init`&quot;">​</a></h2><p>Bootstrap the age identity — generate + store it. Never clobbers an existing identity: a second <code>init</code> reports the current recipient and exits clean</p><p><strong>Usage:</strong> <code>tardigrada init [OPTIONS]</code></p><h6 id="options-1" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-1" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="tardigrada-show" tabindex="-1"><code>tardigrada show</code> <a class="header-anchor" href="#tardigrada-show" aria-label="Permalink to &quot;`tardigrada show`&quot;">​</a></h2><p>Print the <code>age1…</code> recipient of the stored identity — the value tools seal to (cuora vaults, tamias packs, rage recipients files). Goes to stdout bare (scriptable); backend/source context on stderr. Fails when no identity exists — run <code>tardigrada init</code> first</p><p><strong>Usage:</strong> <code>tardigrada show [OPTIONS]</code></p><h6 id="options-2" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-2" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="tardigrada-import" tabindex="-1"><code>tardigrada import</code> <a class="header-anchor" href="#tardigrada-import" aria-label="Permalink to &quot;`tardigrada import`&quot;">​</a></h2><p>Adopt an existing <code>identity.txt</code>-style keyfile as this machine&#39;s identity — parses the file, stores the identity at the configured path (overwrites whatever is there; the old key is gone for good)</p><p><strong>Usage:</strong> <code>tardigrada import [OPTIONS] &lt;FILE&gt;</code></p><h6 id="arguments" tabindex="-1"><strong>Arguments:</strong> <a class="header-anchor" href="#arguments" aria-label="Permalink to &quot;**Arguments:**&quot;">​</a></h6><ul><li><code>&lt;FILE&gt;</code> — Path to the identity.txt keyfile to adopt</li></ul><h6 id="options-3" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-3" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="tardigrada-export" tabindex="-1"><code>tardigrada export</code> <a class="header-anchor" href="#tardigrada-export" aria-label="Permalink to &quot;`tardigrada export`&quot;">​</a></h2><p>Write the identity keyfile out — mode <code>0600</code>, the same format <code>import</code> reads. <code>--out PATH</code> writes a file for moving between tools/machines; bare <code>export</code> prints the <code>AGE-SECRET-KEY-…</code> line to stdout (pipe it into another tool&#39;s keyfile, or <code>rage -e -i /dev/stdin</code>). This is the explicit escape hatch — the value is secret</p><p><strong>Usage:</strong> <code>tardigrada export [OPTIONS]</code></p><h6 id="options-4" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-4" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--out &lt;PATH&gt;</code> — Destination keyfile path (mode <code>0600</code>, parents created)</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="tardigrada-backend" tabindex="-1"><code>tardigrada backend</code> <a class="header-anchor" href="#tardigrada-backend" aria-label="Permalink to &quot;`tardigrada backend`&quot;">​</a></h2><p>Inspect the configured identity backend — always <code>file</code> in v1, plus the resolved keyfile path</p><p><strong>Usage:</strong> <code>tardigrada backend [OPTIONS]</code></p><h6 id="options-5" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-5" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help</li></ul><h2 id="tardigrada-manifest" tabindex="-1"><code>tardigrada manifest</code> <a class="header-anchor" href="#tardigrada-manifest" aria-label="Permalink to &quot;`tardigrada manifest`&quot;">​</a></h2><p>Capabilities, JSON shapes, env vars — agent self-discovery (always JSON)</p><p><strong>Usage:</strong> <code>tardigrada manifest [OPTIONS]</code></p><h6 id="options-6" tabindex="-1"><strong>Options:</strong> <a class="header-anchor" href="#options-6" aria-label="Permalink to &quot;**Options:**&quot;">​</a></h6><ul><li><code>--json</code> — Emit JSON — stable machine shapes on every verb; errors are <code>{&quot;error&quot;: &quot;…&quot;}</code> on stderr with a non-zero exit</li><li><code>--identity-file &lt;PATH&gt;</code> — Identity keyfile path, overriding <code>$TARDIGRADA_IDENTITY_FILE</code> and the XDG default (<code>$XDG_CONFIG_HOME/tardigrada/identity.txt</code>)</li><li><code>-h, --help</code> — Print help</li></ul>',44)])])}const u=t(d,[["render",r]]);export{g as __pageData,u as default};
